                    continue
                seen.add((r, c))
                stack = [(r, c)]
                comp = []
                while stack:
                    y, x = stack.pop()
                    comp.append((y, x))
                    for dy in (-1, 0, 1):
                        for dx in (-1, 0, 1):
                            ny, nx = y + dy, x + dx
                            if (dy or dx) and 0 <= ny < h and 0 <= nx < w:
                                if grid[ny][nx] == color and (ny, nx) not in seen:
                                    seen.add((ny, nx))
                                    stack.append((ny, nx))
                result.append(comp)
        return result

    # Square blocks are marker objects; remaining non-background color is the path.
    markers = []
    marker_colors = set()
    for color in colors:
        for comp in components(color):
            rs = [r for r, c in comp]
            cs = [c for r, c in comp]
            side = max(rs) - min(rs) + 1
            if (side >= 2 and max(cs) - min(cs) + 1 == side
                    and len(comp) == side * side):
                markers.append((color, set(comp)))
                marker_colors.add(color)

    path_colors = colors - marker_colors
    if not markers or not path_colors:
        return [row[:] for row in grid]
    path_color = max(path_colors, key=lambda col:
                     sum(len(c) for c in components(col)))

    color_counts = Counter(color for color, _ in markers)
    endpoint_color = min(color_counts, key=color_counts.get)
    target_color = max(color_counts, key=color_counts.get)
    endpoints = [i for i, (col, _) in enumerate(markers)
                 if col == endpoint_color]
    if len(endpoints) < 2:
        return [row[:] for row in grid]
    source, destination = endpoints[:2]

    paths = components(path_color)
    nm = len(markers)
    graph = [[] for _ in range(nm + len(paths))]

    # Make a bipartite graph linking each line component to adjacent square markers.
    for mi, (_, cells) in enumerate(markers):
        for pi, path in enumerate(paths):
            touches = False
            for r, c in path:
                if any((r + dr, c + dc) in cells
                       for dr in (-1, 0, 1) for dc in (-1, 0, 1)):
                    touches = True
                    break
            if touches:
                pnode = nm + pi
                graph[mi].append(pnode)
                graph[pnode].append(mi)

    def distances(start):
        dist = [-1] * len(graph)
        dist[start] = 0
        q = deque([start])
        while q:
            v = q.popleft()
            for u in graph[v]:
                if dist[u] < 0:
                    dist[u] = dist[v] + 1
                    q.append(u)
        return dist

    ds = distances(source)
    dt = distances(destination)
    if ds[destination] < 0:
        return [row[:] for row in grid]
    length = ds[destination]
    selected = {v for v in range(len(graph))
                if ds[v] >= 0 and dt[v] >= 0 and ds[v] + dt[v] == length}

    out = [row[:] for row in grid]
